#!/usr/bin/env bash
# Harmony web wrapper — single-file installer for Arch Linux
# Installs a native GTK3+WebKit2 wrapper app for https://har.mony.lol
#
# Everything below is plain, readable text: the Python source is embedded
# verbatim (not encoded) in the heredoc below. The one exception is the app
# icon: it's a PNG (binary pixel data), and binary bytes cannot be written
# as literal text in a shell script, so it's base64-encoded just for that
# one block — that's the standard, unavoidable way to embed a binary file
# inside a text file. Nothing else in this script is encoded.
set -e

INSTALL_DIR="$HOME/.local/share/harmony"
BIN_DIR="$HOME/.local/bin"
DESKTOP_DIR="$HOME/.local/share/applications"
ICON_DIR="$HOME/.local/share/icons/hicolor/256x256/apps"
APP_ID="Harmony"

echo "==> Installing dependencies (requires sudo)..."
sudo pacman -S --needed --noconfirm python-gobject gtk3 webkit2gtk-4.1 libayatana-appindicator

echo "==> Creating directories..."
mkdir -p "$INSTALL_DIR" "$BIN_DIR" "$DESKTOP_DIR" "$ICON_DIR"

echo "==> Writing application source (plain text, not encoded)..."
cat > "$INSTALL_DIR/harmony.py" << 'WRAPPER_EOF'
#!/usr/bin/env python3
"""
Simple web wrapper for https://har.mony.lol
Built with GTK3 + WebKit2 (native, lightweight, no Electron/Chromium bundling).
"""

import os
import sys
import gi

gi.require_version("Gtk", "3.0")
gi.require_version("WebKit2", "4.1")
gi.require_version("AyatanaAppIndicator3", "0.1")

from gi.repository import Gtk, WebKit2, Gdk, GLib, AyatanaAppIndicator3 as AppIndicator3

APP_TITLE = "Harmony"
APP_URL = "https://har.mony.lol"

# Must match the .desktop file's name (Harmony.desktop -> "Harmony").
# On Wayland (KDE/KWin, GNOME/Mutter), the compositor identifies windows by this
# app_id and looks up a matching .desktop file to source the taskbar/titlebar icon
# from. The old X11-only set_wmclass() call does nothing under Wayland, which is
# why the icon falls back to a generic one without this.
APP_ID = "Harmony"
GLib.set_prgname(APP_ID)
GLib.set_application_name(APP_TITLE)

# Icon resolution order:
# 1) icon.png sitting next to this script (dev/run-in-place)
# 2) the installed icon theme path (set by install.sh)
_SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
_LOCAL_ICON = os.path.join(_SCRIPT_DIR, "icon.png")
_INSTALLED_ICON = os.path.expanduser(
    "~/.local/share/icons/hicolor/256x256/apps/harmony.png"
)
if os.path.exists(_LOCAL_ICON):
    APP_ICON_PATH = _LOCAL_ICON
elif os.path.exists(_INSTALLED_ICON):
    APP_ICON_PATH = _INSTALLED_ICON
else:
    APP_ICON_PATH = None


class WrapperWindow(Gtk.Window):
    def __init__(self):
        super().__init__(title=APP_TITLE)
        self.set_default_size(1200, 800)

        if APP_ICON_PATH:
            self.set_icon_from_file(APP_ICON_PATH)
            Gtk.Window.set_default_icon_from_file(APP_ICON_PATH)
        else:
            self.set_icon_name("web-browser")

        # X11 fallback (Wayland ignores this; app_id above handles Wayland instead)
        self.set_wmclass(APP_ID, APP_ID)

        # Main vertical box: just the webview, no chrome
        vbox = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=0)
        self.add(vbox)

        # --- WebView ---
        self.webview = WebKit2.WebView()
        settings = self.webview.get_settings()
        settings.set_enable_developer_extras(True)
        settings.set_javascript_can_open_windows_automatically(True)
        settings.set_enable_smooth_scrolling(True)
        self.webview.load_uri(APP_URL)

        # Update window title with page title
        self.webview.connect("notify::title", self.on_title_changed)

        scrolled = Gtk.ScrolledWindow()
        scrolled.add(self.webview)
        vbox.pack_start(scrolled, True, True, 0)

        # Keyboard shortcuts
        self.connect("key-press-event", self.on_key_press)

        # Pressing the window's close (X) button hides the window instead
        # of quitting. The process and webview stay alive in the background,
        # represented by a tray icon (see create_indicator below) — the same
        # StatusNotifierItem protocol the volume/network icons use. Clicking
        # that tray icon (either button) opens a small menu with "Show
        # Harmony" and "Quit" — that's how these tray icons work in general
        # (the volume/network icons behave the same way: click opens a
        # popup/menu rather than "activating" something directly).
        self.connect("delete-event", self.on_delete_event)

        self.indicator = self.create_indicator()

    def on_delete_event(self, _widget, _event):
        self.hide()
        return True  # tells GTK "don't actually close/destroy the window"

    def create_indicator(self):
        indicator = AppIndicator3.Indicator.new(
            APP_ID,
            "harmony",  # icon name — resolved via the icon theme install.sh sets up
            AppIndicator3.IndicatorCategory.APPLICATION_STATUS,
        )
        indicator.set_status(AppIndicator3.IndicatorStatus.ACTIVE)
        indicator.set_title(APP_TITLE)

        menu = Gtk.Menu()

        show_item = Gtk.MenuItem(label=f"Show {APP_TITLE}")
        show_item.connect("activate", lambda _item: self.show_window())
        menu.append(show_item)

        menu.append(Gtk.SeparatorMenuItem())

        quit_item = Gtk.MenuItem(label="Quit")
        quit_item.connect("activate", lambda _item: Gtk.main_quit())
        menu.append(quit_item)

        menu.show_all()
        indicator.set_menu(menu)
        return indicator

    def show_window(self):
        self.deiconify()
        self.show()
        self.present()

    def on_title_changed(self, webview, _param):
        title = webview.get_title()
        self.set_title(f"{title} — {APP_TITLE}" if title else APP_TITLE)

    def on_back(self):
        if self.webview.can_go_back():
            self.webview.go_back()

    def on_forward(self):
        if self.webview.can_go_forward():
            self.webview.go_forward()

    def on_key_press(self, _widget, event):
        keyval = event.keyval
        state = event.state
        ctrl = state & Gdk.ModifierType.CONTROL_MASK

        # Ctrl+R / F5 = reload
        if (ctrl and keyval in (Gdk.KEY_r, Gdk.KEY_R)) or keyval == Gdk.KEY_F5:
            self.webview.reload()
            return True
        # Alt+Left = back
        if state & Gdk.ModifierType.MOD1_MASK and keyval == Gdk.KEY_Left:
            self.on_back()
            return True
        # Alt+Right = forward
        if state & Gdk.ModifierType.MOD1_MASK and keyval == Gdk.KEY_Right:
            self.on_forward()
            return True
        # Ctrl+Q = quit
        if ctrl and keyval in (Gdk.KEY_q, Gdk.KEY_Q):
            Gtk.main_quit()
            return True
        return False


def main():
    win = WrapperWindow()
    win.show_all()
    Gtk.main()


if __name__ == "__main__":
    main()
WRAPPER_EOF
chmod +x "$INSTALL_DIR/harmony.py"

echo "==> Writing app icon (base64 — the only binary blob in this script)..."
base64 -d > "$ICON_DIR/harmony.png" << 'ICON_EOF'

ICON_EOF
# Also drop a copy alongside the script so the app can find it when run in place
cp -f "$ICON_DIR/harmony.png" "$INSTALL_DIR/icon.png"
gtk-update-icon-cache "$HOME/.local/share/icons/hicolor" 2>/dev/null || true

echo "==> Creating launcher script in $BIN_DIR ..."
cat > "$BIN_DIR/harmony" << 'LAUNCHER_EOF'
#!/usr/bin/env bash
exec python3 "$HOME/.local/share/harmony/harmony.py" "$@"
LAUNCHER_EOF
chmod +x "$BIN_DIR/harmony"

echo "==> Installing .desktop entry to $DESKTOP_DIR ..."
# The filename ($APP_ID.desktop) must match the app's Wayland app_id
# (set via GLib.set_prgname in harmony.py) so KWin/Mutter can
# find this file and use its Icon= line for the taskbar/titlebar icon.
cat > "$DESKTOP_DIR/$APP_ID.desktop" << DESKTOP_EOF
[Desktop Entry]
Type=Application
Name=Harmony
Comment=Web wrapper for har.mony.lol
Exec=$BIN_DIR/harmony
Icon=harmony
Categories=Network;WebBrowser;
Terminal=false
StartupWMClass=$APP_ID
DESKTOP_EOF

update-desktop-database "$DESKTOP_DIR" 2>/dev/null || true

echo ""
echo "Done! Launch 'harmony' from a terminal, or find 'Harmony' in your app menu."
echo "If the icon still doesn't show, log out/in (or restart Plasma) to refresh KWin's app_id cache."
